export const DIAGRAM_CHANGE_GROUPS = ['Diagram', 'Nodes', 'Connections', 'Groups', 'Fragments'] as const

export type DiagramChangeGroup = typeof DIAGRAM_CHANGE_GROUPS[number]

export interface DiagramChangeGroupEntry {
