import { ActionUsageValuesService } from './action_usage_values_service'
import type { ActionPopupRuntime } from './action_popup_types'

type ActionPopupBindings = Omit<ActionPopupRuntime, 'runValidationError' | 'settingsStore'>

/** Creates the stores whose lifecycle follows one selected popup action and assignment context. */
export function createActionPopupBindings(
    action: ActionDefinition,
    context: ActionContext,
    requestedRunId?: string,
): ActionPopupBindings {
    const initialRunId = requestedRunId
        ?? actionRunRegistry.getActionRunStore(action.id, context)?.getSnapshot().runId
        ?? null
    const bindingStore = new ActionRunBindingStore(initialRunId)
    bindingStore.trackInitialRun(action.id, context)
    const conversationStore = new ActionConversationStore(action.id, context, bindingStore)
    const historyStore = new ActionHistoryStore(action, context)
    const usageScopeStore = new ActionUsageScopeStore()
    const usageValuesService = new ActionUsageValuesService({
        action,
        bindingStore,
        context,
        conversationStore,
        historyStore,
        scopeStore: usageScopeStore,
    })

    return {
        bindingStore,
        conversationStore,
        historyStore,
        inputStore: new ActionRunInputStore(),
        resultStore: new ActionRunResultStore(),
        scheduleStore: new ActionScheduleStore(),
        usageValuesService,
    }
}

/**
 * The message is rebuilt on every render but only reads the worktree list on the failing
 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
 */
export function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
    if (context.kind !== 'card' && context.kind !== 'project') {
        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for a worktree run'
        return `Action "${action.label}" requires card or project context ${reason}`
    }
    if (context.worktreeError) return context.worktreeError
    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`

    const worktree = Number.parseInt(context.worktree, 10)
    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
    const record = worktreeService.getRecords()[worktree - 1]
    if (!record) return `Configured worktree ${worktree} does not exist`
    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`

    return null
}

import type { ActionRunResult } from '../../../../data/action_run_types'
import type { PopupRunStatus } from '../popup/action_popup_defaults'

interface ActionRunResultSnapshot {
    result: ActionRunResult | null
    runId: string | null
    status: PopupRunStatus
}

type Listener = () => void

const INITIAL_SNAPSHOT: ActionRunResultSnapshot = { result: null, runId: null, status: 'idle' }

/** Owns transient start failures and injected-run results outside popup roots. */
export class ActionRunResultStore {
    private readonly listeners = new Set<Listener>()
    private snapshot = INITIAL_SNAPSHOT

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    setRunning() {
        this.publish({ result: null, runId: null, status: 'running' })
    }

    setRunId(runId: string) {
        this.publish({ ...this.snapshot, runId })
    }

    setResult(result: ActionRunResult) {
        this.publish({ result, runId: null, status: result.status })
    }

    private publish(snapshot: ActionRunResultSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'diagram' | 'file' | 'folder' | 'merge-conflict' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    /** Selected conflicted repository-relative path. */
    conflictFile?: string
    /** Newline-separated conflicted repository-relative paths. */
    conflictFiles?: string
    /** Active desktop conflict session binding. */
    conflictSessionId?: string
    /** Stable diagram record identity. */
    diagramId?: string
    /** Reviewed diagram change instructions captured for one agent handoff. */
    diagramChanges?: string
    /** Stable identity of the selected interactive SVG item. */
    diagramItemId?: string
    /** Selected interactive SVG item's data-diagram-label value. */
    parentNode?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
